import{_ as o,r as s,o as r,c as l,e as t,a as c,s as d}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Record Finder 字段 - October CMS - 3.x","titleTemplate":false,"description":"表单小部件","frontmatter":{"subtitle":"表单小部件","shortname":"Record Finder"},"headers":[{"level":2,"title":"在 Tailor 中使用","slug":"在-tailor-中使用","link":"#在-tailor-中使用","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/element/form/widget-recordfinder.md","filePath":"3.x/zh-cn/element/form/widget-recordfinder.md"}'),p={name:"3.x/zh-cn/element/form/widget-recordfinder.md"};function u(i,e,k,g,m,y){const a=s("pre-heading"),n=s("post-heading");return r(),l("div",null,[t(a),e[0]||(e[0]=c("h1",null,"Record Finder 字段",-1)),t(n),e[1]||(e[1]=d(`<p><code>recordfinder</code> - 渲染一个显示关联记录详细信息的字段。展开该字段将显示一个弹出列表以搜索大量记录。仅支持单数关系。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">list</span><span class="token punctuation">:</span> ~/plugins/rainlab/user/models/user/columns.yaml
</code></pre></div><p>以下<a href="./../form-fields.html">字段属性</a>受支持且常用。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>向用户显示表单字段时使用的名称。</td></tr><tr><td><strong>default</strong></td><td>指定默认字符串值，可选。</td></tr><tr><td><strong>comment</strong></td><td>在字段下方放置描述性注释。</td></tr><tr><td><strong>keyFrom</strong></td><td>关系中用作键的列名。默认值：<code>id</code>。</td></tr><tr><td><strong>nameFrom</strong></td><td>关系中用于显示名称的列名。默认值：<code>name</code>。</td></tr><tr><td><strong>descriptionFrom</strong></td><td>关系中用于显示描述的列名。默认值：<code>description</code>。</td></tr><tr><td><strong>title</strong></td><td>在弹出窗口标题部分显示的文本。</td></tr><tr><td><strong>list</strong></td><td>配置数组或列表列定义文件的引用。</td></tr><tr><td><strong>filter</strong></td><td>过滤器范围定义文件的引用，请参阅<a href="./../../extend/lists/filters.html">后端列表过滤器</a>。</td></tr><tr><td><strong>showSetup</strong></td><td>显示设置按钮以配置列表列和每页记录数。默认值：<code>false</code></td></tr><tr><td><strong>structure</strong></td><td>启用只读结构化列表以选择记录，请参阅<a href="./../../extend/lists/structures.html">排序记录文章</a>。设置为 <code>false</code> 以禁用，否则当模型使用树形界面时将自动启用。</td></tr><tr><td><strong>defaultSort</strong></td><td>在用户偏好未定义时设置默认排序列和方向。支持字符串或包含 <code>column</code> 和 <code>direction</code> 键的数组。方向可以是 <code>asc</code>（升序，默认）或 <code>desc</code>（降序）。</td></tr><tr><td><strong>recordsPerPage</strong></td><td>每页显示的记录数，使用 0 表示不分页。默认值：<code>10</code></td></tr><tr><td><strong>conditions</strong></td><td>指定应用于列表模型查询的原始 where 查询语句。</td></tr><tr><td><strong>modelScope</strong></td><td>将<a href="./../../extend/database/model.html">模型查询范围</a>方法应用于<strong>关联表单模型</strong>，可以是模型方法名或静态 PHP 类方法（<code>Class::method</code>）。第一个参数将包含小部件将其值附加到的模型，即父模型。</td></tr><tr><td><strong>searchMode</strong></td><td>定义搜索策略，可选包含所有词、任意词或精确短语。支持的选项：all、any、exact。默认值：<code>all</code>。</td></tr><tr><td><strong>searchScope</strong></td><td>指定在<strong>关联表单模型</strong>中定义的<a href="./../../extend/database/model.html">模型查询范围</a>方法应用于搜索查询，第一个参数将包含搜索词。</td></tr><tr><td><strong>useRelation</strong></td><td>使用字段名称作为关系名称直接与父模型交互的标志。默认值：<code>true</code>。禁用以仅返回所选模型的 ID</td></tr><tr><td><strong>modelClass</strong></td><td>当 <code>useRelation</code> 为 <code>false</code> 时用于列出记录的模型类</td></tr><tr><td><strong>popupSize</strong></td><td>更改查找器弹出窗口的大小，可选：<code>giant</code>、<code>huge</code>、<code>large</code>、<code>small</code>、<code>tiny</code> 或 <code>adaptive</code>。默认值：<code>huge</code></td></tr><tr><td><strong>inlineOptions</strong></td><td>在所选记录旁边显示带按钮的字段，如果水平空间有限，请禁用此模式。默认值：<code>true</code>。</td></tr></tbody></table></div><p>您可以使用 <code>recordsPerPage</code> 属性限制每页的记录数。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div><p>使用 <code>title</code> 属性更改管理表单的标题。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Find A User
</code></pre></div><p>选择记录后，可以使用 <code>nameFrom</code> 和 <code>descriptionFrom</code> 属性从模型属性中选择显示属性。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> name
    <span class="token key atrule">descriptionFrom</span><span class="token punctuation">:</span> email
</code></pre></div><p>如果检测到<a href="./../../extend/lists/structures.html">模型结构</a>，列表将以结构形式显示。可以使用 <strong>structure</strong> 属性显式禁用或启用。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">structure</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><h2 id="在-tailor-中使用"><a href="#在-tailor-中使用" class="header-anchor">#</a> 在 Tailor 中使用</h2><p>当 <code>recordfinder</code> 字段用作 <a href="./../../cms/tailor/content-fields.html">Tailor 中的内容字段</a>时，需要指定 <code>modelClass</code> 属性来定义和查找模型关系。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Product
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/october/test/models/product/columns.yaml
</code></pre></div><p>当 <code>maxItems</code> 设置为 <strong>1</strong> 时，关系定义为 <code>belongsTo</code> 关系。否则，关系定义为 <code>belongsToMany</code>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Tag
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p><code>inverse</code> 属性可以设置为关联模型上的关系名称。这将根据 <code>maxItems</code> 设置和关联模型的关系类型将关系定义更改为 <code>hasOne</code>、<code>hasMany</code> 或 <code>belongsToMany</code>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tags</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Tags
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Tag
    <span class="token key atrule">inverse</span><span class="token punctuation">:</span> tags
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../../cms/tailor/models.html">Tailor 模型</a></li><li><a href="./../../extend/database/relations.html">数据库关系</a></li></ul></div>`,21))])}const b=o(p,[["render",u]]);export{f as __pageData,b as default};
